package ru.studyplanner.app;
import android.app.*;import android.content.*;import org.json.*;import java.time.*;
public class Reminder extends BroadcastReceiver {
 static void channel(Context c){c.getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("deadlines","Учебные напоминания",NotificationManager.IMPORTANCE_HIGH));}
 static PendingIntent pi(Context c,String id,String title,String date){Intent i=new Intent(c,Reminder.class).setAction("reminder:"+id).putExtra("title",title).putExtra("date",date);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void sync(Context c,String s){try{android.content.SharedPreferences p=c.getSharedPreferences("reminders",0);AlarmManager a=c.getSystemService(AlarmManager.class);JSONArray old=new JSONArray(p.getString("tasks","[]"));for(int n=0;n<old.length();n++){JSONObject t=old.getJSONObject(n);a.cancel(pi(c,t.getString("id"),"",""));}JSONArray arr=new JSONArray(s);p.edit().putString("tasks",s).apply();for(int n=0;n<arr.length();n++){JSONObject t=arr.getJSONObject(n);if(t.optBoolean("completed")||!t.optBoolean("remind2DaysBefore")||t.optBoolean("isDemo"))continue;LocalDate due=LocalDate.parse(t.getString("dueDate"));long time=due.minusDays(2).atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();if(time>System.currentTimeMillis())a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time,pi(c,t.getString("id"),t.getString("title"),due.toString()));}}catch(Exception e){android.util.Log.e("Planner","Schedule failed",e);}}
 public void onReceive(Context c,Intent i){if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())){sync(c,c.getSharedPreferences("reminders",0).getString("tasks","[]"));return;}notifyUser(c,i.getAction().hashCode(),i.getStringExtra("title"),"Срок сдачи: "+i.getStringExtra("date"));}
 static void notifyUser(Context c,int id,String title,String body){channel(c);PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);c.getSystemService(NotificationManager.class).notify(id,new Notification.Builder(c,"deadlines").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(body).setContentIntent(open).setAutoCancel(true).build());}
}